// Skip List — Algorithms, route: jsx
// Source: original:essay/skip-list
//
// Self-contained: every local import is inlined below. Requires only react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';

// ---- inlined from skiplist ----
/**
 * A skip list built by seeded coin flips over ~28 sorted keys, plus the visit trace of one
 * scripted search. The build order and every tower height are fixed by the seed.
 */

const SEED = 20260822;
const MAX_LEVEL = 5;

/** mulberry32: a fixed seed keeps every build identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(SEED);

const KEYS: number[] = [];
{
  const seen = new Set<number>();
  while (KEYS.length < 28) {
    const key = 2 + Math.floor(random() * 96);
    if (!seen.has(key)) {
      seen.add(key);
      KEYS.push(key);
    }
  }
  KEYS.sort((a, b) => a - b);
}

/** Tower height per key: geometric coin flips, capped at MAX_LEVEL. */
const HEIGHTS = KEYS.map(() => {
  let h = 1;
  while (h < MAX_LEVEL && random() < 0.5) ++h;
  return h;
});

const LEVELS = Math.max(...HEIGHTS);

/** The scripted search target: a key in the last quarter, so the path travels. */
const TARGET_INDEX = 24;
const TARGET = KEYS[TARGET_INDEX];

interface Visit {
  /** Column landed on: -1 is the head sentinel, otherwise an index into KEYS. */
  column: number;
  level: number;
  kind: 'start' | 'advance' | 'descend' | 'found';
}

/** The standard descent: advance while the next tower at this level stays below the target. */
const visits: Visit[] = [];
{
  let column = -1;
  visits.push({ column, level: LEVELS - 1, kind: 'start' });
  for (let level = LEVELS - 1; level >= 0; --level) {
    if (level < LEVELS - 1) visits.push({ column, level, kind: 'descend' });
    let next = column + 1;
    while (next < KEYS.length && HEIGHTS[next] <= level) ++next;
    while (next < KEYS.length && KEYS[next] < TARGET) {
      column = next;
      visits.push({ column, level, kind: 'advance' });
      ++next;
      while (next < KEYS.length && HEIGHTS[next] <= level) ++next;
    }
  }
  visits.push({ column: TARGET_INDEX, level: 0, kind: 'found' });
}

const VISITED_NODES = new Set(visits.filter((v) => v.column >= 0).map((v) => v.column))
  .size;

const TICK_MS = 120;
const BUILD_END = KEYS.length;
const PAUSE = 4;
const VISIT_TICKS = 3;
const SEARCH_END = BUILD_END + PAUSE + VISIT_TICKS * visits.length;
const HOLD_TICKS = 26;
const END = SEARCH_END + HOLD_TICKS;
const CURRENT = '#e0538a';
const FOUND = '#3fa66a';

export default function SkipList({ width }: { width: number }) {
  const w = Math.max(1, width);
  const colW = w / (KEYS.length + 2);
  const rowH = colW * 1.05;
  const top = 14;
  const gridH = LEVELS * rowH;
  const height = Math.round(top + gridH + 40);
  const boxW = colW * 0.62;
  const boxH = rowH * 0.62;

  // The SSR frame is the completed search; the effect rewinds through build and descent.
  const [step, setStep] = useState(SEARCH_END);

  useEffect(() => {
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s >= END ? 0 : s + 1)), TICK_MS);
    return () => window.clearInterval(id);
  }, []);

  const built = Math.min(step, BUILD_END);
  const visitsShown = Math.max(
    0,
    Math.min(Math.floor((step - BUILD_END - PAUSE) / VISIT_TICKS) + 1, visits.length)
  );

  const x = (column: number) => (column + 1.5) * colW;
  const y = (level: number) => top + (LEVELS - 1 - level) * rowH;

  /** Level rails: at each level, one line from the head to the last tower tall enough. */
  const rails = useMemo(() => {
    const lines: { level: number; toColumn: number }[] = [];
    for (let level = 0; level < LEVELS; ++level) {
      let last = -1;
      for (let c = 0; c < built; ++c) if (HEIGHTS[c] > level) last = c;
      if (last >= 0) lines.push({ level, toColumn: last });
    }
    return lines;
  }, [built]);

  const visited = useMemo(() => visits.slice(0, visitsShown), [visitsShown]);
  const touched = useMemo(
    () => new Set(visited.map((v) => `${v.column}:${v.level}`)),
    [visited]
  );
  const nodesSoFar = useMemo(
    () => new Set(visited.filter((v) => v.column >= 0).map((v) => v.column)).size,
    [visited]
  );

  if (width === 0) return null;

  const found = visitsShown >= visits.length;
  const current = visitsShown > 0 ? visits[visitsShown - 1] : null;
  const keyFont = Math.max(6, Math.min(10, colW * 0.44));

  return (
    <svg
      viewBox={`0 0 ${w} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="A skip list of 28 keys built by seeded coin flips, then one search descending it: the path drops level by level and skips whole spans of the list, so the dim, never-visited majority is the speed the random towers bought"
    >
      {rails.map(({ level, toColumn }) => (
        <line
          key={level}
          x1={x(-1)}
          y1={y(level) + boxH / 2}
          x2={x(toColumn)}
          y2={y(level) + boxH / 2}
          stroke="var(--line)"
          strokeWidth={1}
        />
      ))}
      {Array.from({ length: LEVELS }, (_, level) => (
        <rect
          key={level}
          x={x(-1) - boxW / 2}
          y={y(level)}
          width={boxW}
          height={boxH}
          rx={2}
          fill={touched.has(`-1:${level}`) ? 'var(--accent)' : 'var(--muted)'}
          opacity={touched.has(`-1:${level}`) ? 0.9 : 0.3}
        />
      ))}
      {KEYS.map((_, c) =>
        c >= built
          ? null
          : Array.from({ length: HEIGHTS[c] }, (_, level) => {
              const isCurrent = current !== null && current.column === c && current.level === level;
              const isFound = found && c === visits[visits.length - 1].column && level === 0;
              const hit = touched.has(`${c}:${level}`);
              return (
                <rect
                  key={`${c}:${level}`}
                  x={x(c) - boxW / 2}
                  y={y(level)}
                  width={boxW}
                  height={boxH}
                  rx={2}
                  fill={isFound ? FOUND : isCurrent ? CURRENT : hit ? 'var(--accent)' : 'var(--muted)'}
                  opacity={isFound || isCurrent ? 1 : hit ? 0.9 : 0.22}
                />
              );
            })
      )}
      {visited.length > 1 && (
        <path
          d={visited
            .map((v, k) => `${k ? 'L' : 'M'}${x(v.column).toFixed(1)},${(y(v.level) + boxH / 2).toFixed(1)}`)
            .join('')}
          fill="none"
          stroke="var(--accent)"
          strokeWidth={2}
          strokeLinejoin="round"
          opacity={0.9}
        />
      )}
      {KEYS.map((key, c) => (
        <text
          key={c}
          x={x(c)}
          y={top + gridH + keyFont + 4}
          textAnchor="middle"
          fontSize={keyFont}
          fill={c < built ? (found && c === visits[visits.length - 1].column ? FOUND : 'var(--muted)') : 'var(--line)'}
          fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
        >
          {key}
        </text>
      ))}
      <text
        x={x(-1)}
        y={top + gridH + keyFont + 4}
        textAnchor="middle"
        fontSize={keyFont}
        fill="var(--muted)"
      >
        −∞
      </text>
      <text x={4} y={height - 6} fill="var(--muted)" fontSize={11}>
        {step < BUILD_END + PAUSE
          ? `coin flips raise tower ${built} of ${KEYS.length}`
          : found
            ? `found ${TARGET} · visited ${VISITED_NODES} of ${KEYS.length} nodes`
            : `searching for ${TARGET} · visited ${nodesSoFar} of ${KEYS.length} nodes`}
      </text>
    </svg>
  );
}
